// Where each invader's picture starts and ends in its 16-pixel cell (both frames): the march turns when the
// outermost live invader's picture reaches the edge.
module inv_invader_extent (
	input	wire	[1:0]		kind,
	output	logic	[3:0]		first,
	output	logic	[3:0]		last
	);
always_comb
	case (kind)
		2'd0: begin first = 4'd2; last = 4'd13; end
		2'd1: begin first = 4'd2; last = 4'd12; end
		2'd2: begin first = 4'd4; last = 4'd11; end
		default: begin first = 4'd0; last = 4'd15; end
	endcase
endmodule
